import{z as i,x as n,o as e,c as p,q as r,j as t,D as A,d as a,s as B,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"蒸馏保底与探索上限","description":"","frontmatter":{"title":"蒸馏保底与探索上限","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/distill-vs-explore.md","filePath":"llm/distill-vs-explore.md","lastUpdated":1791063341000}'),d={name:"llm/distill-vs-explore.md"};function F(D,E,m,h,c,u){const s=n("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="蒸馏保底与探索上限" tabindex="-1">蒸馏保底与探索上限 <a class="header-anchor" href="#蒸馏保底与探索上限" aria-label="Permalink to &quot;蒸馏保底与探索上限&quot;">​</a></h1><div class="epigraph"><p>蒸馏搬运教师分布里已有的东西，探索购买分布外的新解；把两者混为一谈的闭环，要么把重复当进步，要么把浪费当探索。</p><footer>—— Agarwal 等, On-Policy Distillation of Language Models（2023）；Qwen3 Technical Report</footer></div><p><a href="/llm/weak-to-strong-closure">上一课</a>说弱奖励能激发强先验，但那是监督侧的故事；闭环里还有一个更日常的分叉：每轮迭代的能力增量，该走蒸馏还是走探索。蒸馏把教师分布搬进学生——<a href="/llm/on-policy-distillation">on-policy 蒸馏</a>以学生自己的 rollout 为底、逐步反向 KL 当稠密奖励，代价约为 RL 的十分之一；探索用验证器在学生自己的分布里找教师没有的解。本课写两者的分工边界与判据，不重写 <a href="/llm/rlvr">RLVR</a> 的机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失效各有对称面。只蒸馏的闭环安全、便宜、可复现，但天花板是教师的支撑集：教师没走过的分叉，学生一步也学不到；若目标能力是「解决教师也解不出的题」，蒸馏在结构上不可能。只探索的闭环相反：稀疏的 0/1 奖励在能力不足的学生上几乎是噪声，格式与基本推理会被探索噪声打碎，训练成本高出一个量级。常见的两个错：把前者当进步——每轮指标都在涨，涨的全是教师会的东西；或把后者当算力问题，以为探索不足用更大的批量就能砸出来，实际上学生支撑里根本没有可捞的解。</p><p><span class="marginnote">「支撑集」借自概率论：一个分布在哪些点上给出非零概率，那些点就是它的支撑集。「天花板是教师的支撑集」意思是——学生只能学到教师会输出的行为，教师从未产出过的解法对蒸馏而言不存在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分工的判据用两个数：教师覆盖与 pass@\\(k\\)。对一批闭环外的验证题，先看教师能否解，再看学生 pass@\\(k\\) 相对 pass@1 的尾部。教师解得出、需求只是把行为对齐到学生——纯蒸馏：能力已在分布内，on-policy 蒸馏的稠密信号最省，Qwen3 的账是 1,800 GPU 小时到 AIME 74.4%，而 RL 花 17,920 小时只到 67.6%。教师解不出、但 pass@\\(k\\) 明显高于 pass@1——探索有真实空间：学生偶尔摸到验证器接受的解，策略梯度能把它从尾部捞成主流，此时蒸馏无货可搬。两头都低——先蒸馏拉进邻域或换域，空支撑上的探索是纯噪声。</p><p><span class="marginnote">把 Qwen3 那笔账展开看：蒸馏 1,800 GPU 小时到 AIME 74.4%，RL 探索 17,920 小时只到 67.6%——约十倍成本还低 6.8 个点。这不是 RL 不行，而是「能力已在教师分布内」时，探索在白付学费。</span></p>',9)),(e(),t(o,null,{default:A(()=>[B(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AD%E7%8E%AF%E5%A4%96%E7%9A%84%E9%AA%8C%E8%AF%81%E9%A2%98%E9%9B%86%22%5D%20--%3E%20T%7B%22%E6%95%99%E5%B8%88%E8%83%BD%E8%A7%A3%3F%22%7D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20D%5B%22%E8%92%B8%E9%A6%8F%EF%BC%9A%E7%A8%A0%E5%AF%86%E5%8F%8D%E5%90%91%20KL%22%5D%0A%20%20T%20--%3E%7C%E5%90%A6%7C%20K%7B%22%E5%AD%A6%E7%94%9F%20pass%40k%20%E9%AB%98%E4%BA%8E%20pass%401%3F%22%7D%0A%20%20K%20--%3E%7C%E6%98%AF%7C%20R%5B%22RL%20%E6%8E%A2%E7%B4%A2%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%99%A8%E6%8D%9E%E6%96%B0%E8%A7%A3%22%5D%0A%20%20K%20--%3E%7C%E5%90%A6%7C%20P%5B%22%E5%85%88%E8%92%B8%E9%A6%8F%E8%BF%9B%E9%82%BB%E5%9F%9F%EF%BC%8C%E6%88%96%E6%8D%A2%E5%9F%9F%22%5D%0A%20%20D%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20R%20--%3E%20N%0A%20%20P%20--%3E%20Q2%5B%22%E9%87%8D%E4%BC%B0%E6%95%99%E5%B8%88%E8%A6%86%E7%9B%96%E4%B8%8E%E5%B0%BE%E9%83%A8%22%5D%0A%20%20Q2%20--%3E%20T%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[a("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,[a("上限差异来自信号结构。蒸馏的每 token 梯度都钉在教师的条件分布上，信息密、方差小，但目标函数的极值在教师分布之内——反向 KL 的模式寻求也只是在教师支撑里挑学生能到的模式。探索的信号在序列末尾只有一个比特，可它由环境真值签发：一个教师从未产出的新解法，只要过验证器就有正梯度。这是自训练闭环里唯一结构性地超越教师的通道，也是弱到强问题的可验证解法。代价在方差与越界：奖励稀疏时优势估计噪声大，验证器有缝时探索会优先钻缝——过优化与奖励黑客是探索税，"),l("a",{href:"/llm/rlvr"},"RLVR"),a(" 的过优化记录就是账单。")],-1)),(e(),t(o,null,{default:A(()=>[B(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20DIST%5B%22%E8%92%B8%E9%A6%8F%3A%20%E7%A8%A0%E5%AF%86%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20%20%20D1%5B%22%E5%AD%A6%E7%94%9F%20rollout%20%E7%9A%84%E6%AF%8F%E4%B8%AA%20token%22%5D%20--%3E%20D2%5B%22%E9%80%90%E6%AD%A5%E5%AF%B9%E6%95%99%E5%B8%88%E7%AE%97%E5%8F%8D%E5%90%91%20KL%22%5D%20--%3E%20D3%5B%22%E4%BF%A1%E5%8F%B7%E5%AF%86%E3%80%81%E6%96%B9%E5%B7%AE%E5%B0%8F%2C%20%E4%BD%86%E4%B8%8A%E9%99%90%E9%94%81%E5%9C%A8%E6%95%99%E5%B8%88%E6%94%AF%E6%92%91%E9%9B%86%22%5D%0A%20%20end%0A%20%20subgraph%20EXP%5B%22%E6%8E%A2%E7%B4%A2%3A%20%E7%A8%80%E7%96%8F%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20%20%20E1%5B%22%E5%AD%A6%E7%94%9F%E8%87%AA%E5%B7%B1%E9%87%87%E6%A0%B7%E5%A4%9A%E6%9D%A1%E8%A7%A3%22%5D%20--%3E%20E2%5B%22%E5%BA%8F%E5%88%97%E6%9C%AB%E5%B0%BE%E4%B8%80%E4%B8%AA%E6%AF%94%E7%89%B9%3A%20%E8%BF%87%2F%E4%B8%8D%E8%BF%87%E9%AA%8C%E8%AF%81%E5%99%A8%22%5D%20--%3E%20E3%5B%22%E6%96%B0%E8%A7%A3%E8%BF%87%E9%AA%8C%E8%AF%81%E5%99%A8%E5%8D%B3%E6%8B%BF%E6%AD%A3%E6%A2%AF%E5%BA%A6%2C%20%E5%8F%AF%E8%B6%85%E8%B6%8A%E6%95%99%E5%B8%88%22%5D%0A%20%20end%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">pass@\\(k\\)（Chen 等 2021）是 \\(k\\) 条采样至少一条通过的比例。pass@\\(k\\) 高而 pass@1 低，说明解已在学生分布的支撑里、只是排序不行——这正是 RL 的领地；蒸馏对这种「会而不稳」也有效，区别是它只能搬教师已有的排序。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>蒸馏就够的情形比想象多：风格与格式对齐、把已验证行为迁到更小的模型、以及验证器太弱不敢让探索跑的域——最后一条是防奖励黑客的保守选择。必须探索的情形：教师覆盖不到的前沿题型，以及 <a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>说过的处境——学生学的是文本痕迹，不是产出痕迹的搜索能力。最常见的谎报是拿蒸馏学生的涨分当探索成果；审计办法是查训练数据来源：每条有效梯度是否都来自教师签发的分布，还是至少有一部分来自验证器对新解的判定。</p><p><span class="marginnote">「拿蒸馏涨分当探索成果」之所以常见，是因为它几乎无法从曲线上看出来——两条曲线都在上扬。审计只有一个入口：查每条有效梯度的出处，是教师签发的分布，还是验证器对新解的判定。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蒸馏的上限是教师支撑集；探索是闭环里唯一结构性的超越通道。</li><li>判据看教师覆盖与 pass@\\(k\\)：能力在分布内时蒸馏便宜一个量级。</li><li>教师解不出且 pass@\\(k\\) 有尾部，才值得开探索。</li><li>弱验证器下的探索先学会钻缝，探索税要用验证器审计来付。</li><li>出处：Agarwal 等（2023）与 Qwen3 报告的成本对照；pass@\\(k\\) 出自 Chen 等 2021。</li></ul>',6))])}const _=i(d,[["render",F]]);export{f as __pageData,_ as default};
